import { TaskQueue } from './TaskQueue';
const queue = new TaskQueue();
export function saveChanges(write: () => Promise<void>) {
  queue.enqueue(write);
  return queue.drain();
}

export class TaskQueue {
  private jobs: Array<() => Promise<void>> = [];
  private running = false;
  enqueue(job: () => Promise<void>) { this.jobs.push(job); }
  async drain() {
    if (this.running) return;
    this.running = true;
    try {
      while (this.jobs.length) {
        await this.jobs[0]();
        this.jobs.shift();
      }
    } finally { this.running = false; }
  }
}

import { TaskQueue } from '../src/TaskQueue';
import { strict as assert } from 'node:assert';
export async function fifoExample() {
  const queue = new TaskQueue();
  const seen: number[] = [];
  queue.enqueue(async () => { seen.push(1); });
  queue.enqueue(async () => { seen.push(2); });
  await queue.drain();
  assert.deepEqual(seen, [1, 2]);
}
